from html.parser import HTMLParser
html=open('[REDACTED LOCAL PATH]').read()
start=html.index('id=\"geneListing\"')
# end at closing div maybe later; find next tables enough
seg=html[start:start+100000]
class P(HTMLParser):
    def __init__(self):
        super().__init__(); self.in_table=False; self.in_row=False; self.in_cell=False; self.celltag=''; self.cell=[]; self.rows=[]; self.cur=[]
    def handle_starttag(self,tag,attrs):
        a=dict(attrs)
        if tag=='table' and not self.in_table:
            self.in_table=True
        elif self.in_table and tag=='tr':
            self.in_row=True; self.cur=[]
        elif self.in_row and tag in ('td','th'):
            self.in_cell=True; self.celltag=tag; self.cell=[]
    def handle_endtag(self,tag):
        if self.in_cell and tag==self.celltag:
            self.in_cell=False; self.cur.append(''.join(self.cell).strip())
        elif self.in_row and tag=='tr':
            self.in_row=False; self.rows.append(self.cur)
        elif self.in_table and tag=='table':
            self.in_table=False
    def handle_data(self,data):
        if self.in_cell: self.cell.append(data)
p=P(); p.feed(seg)
rows=[r for r in p.rows if len(r)>=3]
print('rows',len(rows))
print(rows[:5])
genes=[]
for r in rows:
    genes.append(r[2])
# but gene symbol may be link; handle_data gets it
print(genes[:10],len(genes))
inp=[x.strip() for x in open('/workspace/inputs/characterize.response.q1.txt') if x.strip()]
gs=set(g.upper() for g in genes)
over=[x for x in inp if x.upper() in gs]
print('overlap',len(over),'/',len(inp))
print(over)
PY"

